-- RAW verification of demo series (SELECT only). Scope: PART_001-004, plant HZL_DEMO_05,
-- ZSPR/ZSPN, IS_BACKCAST_PERIOD='N', POSTING_DATE 2024-01-01..2025-12-31, movement 261/262.
-- Result observed: N_TOP50_MATERIALS=50, SUM_NET_QTY=171630.000, NONZERO_ROWS=1046 (matches demo_net_issue_series.sql).
WITH SRC AS (
  SELECT PLANT_ID, MATERIAL_ID, MOVEMENT_TYPE, TO_DECIMAL(QUANTITY,18,3) AS Q, POSTING_DATE FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_001 WHERE IS_BACKCAST_PERIOD='N' AND MOVEMENT_TYPE IN ('261','262') AND POSTING_DATE >= '2024-01-01' AND POSTING_DATE <= '2025-12-31'
  UNION ALL SELECT PLANT_ID, MATERIAL_ID, MOVEMENT_TYPE, TO_DECIMAL(QUANTITY,18,3), POSTING_DATE FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_002 WHERE IS_BACKCAST_PERIOD='N' AND MOVEMENT_TYPE IN ('261','262') AND POSTING_DATE >= '2024-01-01' AND POSTING_DATE <= '2025-12-31'
  UNION ALL SELECT PLANT_ID, MATERIAL_ID, MOVEMENT_TYPE, TO_DECIMAL(QUANTITY,18,3), POSTING_DATE FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_003 WHERE IS_BACKCAST_PERIOD='N' AND MOVEMENT_TYPE IN ('261','262') AND POSTING_DATE >= '2024-01-01' AND POSTING_DATE <= '2025-12-31'
  UNION ALL SELECT PLANT_ID, MATERIAL_ID, MOVEMENT_TYPE, TO_DECIMAL(QUANTITY,18,3), POSTING_DATE FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_004 WHERE IS_BACKCAST_PERIOD='N' AND MOVEMENT_TYPE IN ('261','262') AND POSTING_DATE >= '2024-01-01' AND POSTING_DATE <= '2025-12-31'
),
SCOPED AS (
  SELECT S.* FROM SRC S WHERE S.PLANT_ID='HZL_DEMO_05'
    AND S.MATERIAL_ID IN (SELECT MATERIAL_ID FROM VEDANTA_POC.DIM_MATERIAL WHERE MATERIAL_TYPE IN ('ZSPR','ZSPN'))
),
TOP50 AS (
  SELECT MATERIAL_ID FROM (SELECT MATERIAL_ID, SUM(CASE WHEN MOVEMENT_TYPE='261' THEN Q ELSE -Q END) AS NET FROM SCOPED GROUP BY MATERIAL_ID ORDER BY NET DESC LIMIT 50)
),
MONTHLY AS (
  SELECT MATERIAL_ID, SUBSTRING(POSTING_DATE,1,7) AS YM, SUM(CASE WHEN MOVEMENT_TYPE='261' THEN Q ELSE -Q END) AS NET_QTY
  FROM SCOPED WHERE MATERIAL_ID IN (SELECT MATERIAL_ID FROM TOP50) GROUP BY MATERIAL_ID, SUBSTRING(POSTING_DATE,1,7)
)
SELECT COUNT(*) AS N_TOP50_MATERIALS, (SELECT SUM(NET_QTY) FROM MONTHLY) AS SUM_NET_QTY, (SELECT COUNT(*) FROM MONTHLY WHERE NET_QTY<>0) AS NONZERO_ROWS FROM TOP50
